///--------------------------------------------------------------------------//
//! \desc  Use this method to search if a key was registered in Reg_Table
//!        

//! \assume Reg_Table is a valid pointer

//! \notes  Private method

//! \param  reg       the Reg_Table object
//! \param  id        the Reg_Id key


//! \return Reg_Table_Id    - non-NULL if the table mapped to id key was found
//!                         - NULL if the table not exist
//--------------------------------------------------------------------------//


Reg_Table_Id reg_check_id( Reg_Table reg  , Reg_Id id )
{
    Reg_Table_Id curr = reg->next ;

    while( curr )
    {
        if( curr->id == id ) break ;
        
        curr = curr->next_id ;
    } 
    
    return curr  ;
}

